        SpcPreviewPlayer spcPlayer;MusicActivityMeters activity;MidiPreview midiPlayer;CancellationTokenSource previewCancel;
        void StopAudio(){if(previewCancel!=null){previewCancel.Cancel();previewCancel.Dispose();previewCancel=null;}if(spcPlayer!=null){spcPlayer.Dispose();spcPlayer=null;}if(activity!=null)activity.Stop();if(midiPlayer!=null){midiPlayer.Dispose();midiPlayer=null;}if(samplePlayer!=null)samplePlayer.Stop();}
        void PlayWave(byte[] bytes){if(samplePlayer!=null){samplePlayer.Stop();samplePlayer.Dispose();}if(sampleStream!=null)sampleStream.Dispose();sampleStream=new MemoryStream(bytes);samplePlayer=new System.Media.SoundPlayer(sampleStream);samplePlayer.Play();}
        void AddMusicTab(){
            var tab=new TabPage("Music"){BackColor=Theme.Panel};tabs.TabPages.Add(tab);
            var split=new SplitContainer{Dock=DockStyle.Fill,Width=1160,SplitterDistance=210,FixedPanel=FixedPanel.Panel1};tab.Controls.Add(split);
            musicMaps.Dock=DockStyle.Fill;musicMaps.BackColor=Theme.Background;musicMaps.ForeColor=Theme.Text;split.Panel1.Controls.Add(musicMaps);
            split.Panel1.Controls.Add(new Label{Dock=DockStyle.Top,Height=65,Text="Choose music to edit\nTitle, intermission or a level.",Padding=new Padding(8),ForeColor=Theme.Mint});
            var details=AudioReport();details.Text="Choose your base ROM. Import MID / MUS for an original level or a PWAD map.\r\n\r\nInstruments opens channel/program assignments and native bank selection. Auto convert chooses the closest native bank and simplifies an intricate score to fit.\r\n\r\nPlay source uses Windows MIDI synthesis. Play converted executes the retail SPC driver and native soundbank, just like gameplay.";
            var settings=new FlowLayoutPanel{Dock=DockStyle.Top,Height=104,AutoScroll=true,Padding=new Padding(8)};
            var voices=new NumericUpDown{Minimum=1,Maximum=8,Value=6,Width=48};var duration=new NumericUpDown{Minimum=0,Maximum=3600,Value=0,Width=64};var previewSeconds=new NumericUpDown{Minimum=1,Maximum=600,Value=60,Width=56};var loop=new CheckBox{Text="Loop",Checked=true,AutoSize=true};
            settings.Controls.Add(new Label{Text="Voices",AutoSize=true});settings.Controls.Add(voices);settings.Controls.Add(new Label{Text="Limit seconds (0 = full)",AutoSize=true});settings.Controls.Add(duration);settings.Controls.Add(loop);settings.Controls.Add(new Label{Text="Preview seconds",AutoSize=true});settings.Controls.Add(previewSeconds);var keepAssignments=new CheckBox{Text="Keep instrument assignments when fitting",Checked=true,AutoSize=true};settings.Controls.Add(keepAssignments);
            var actions=new FlowLayoutPanel{Dock=DockStyle.Top,Height=136,AutoScroll=true,Padding=new Padding(8)};
            var fewerVoices=new CheckBox{Text="Allow fewer voices to keep the full song",Checked=false,AutoSize=true};settings.Controls.Add(fewerVoices);
            settings.Controls.Add(new Label{Text="6: two voices free for effects.  8: effects share music voices.",AutoSize=true,ForeColor=Theme.Mint,Margin=new Padding(12,5,3,3)});
            var natural=new CheckBox{Text="Natural note releases",Checked=true,AutoSize=true};var releaseMs=new NumericUpDown{Minimum=0,Maximum=500,Value=0,Width=56};settings.Controls.Add(natural);settings.Controls.Add(new Label{Text="Extra tail protection (ms)",AutoSize=true});settings.Controls.Add(releaseMs);tips.SetToolTip(natural,"Use the native SNES instrument release envelopes instead of abruptly silencing each MIDI note. Apply settings rebuilds the score.");tips.SetToolTip(releaseMs,"Natural envelopes still ring at zero. Reserve spare voices for this long after a note ends. Fading tails can still be reused when all voices are busy; MIDI note-on timing is preserved.");natural.CheckedChanged+=delegate{releaseMs.Enabled=natural.Checked;};
            var import=Theme.Button("Import MID / MUS...");var apply=Theme.Button("Apply settings");var autoMusic=Theme.Button("Auto convert / fit");var instruments=Theme.Button("Instruments / channels...");var sourcePlay=Theme.Button("Play source");var convertedPlay=Theme.Button("Play converted (SPC)");var stop=Theme.Button("Stop playback");var all=Theme.Button("Assign to included maps");var reset=Theme.Button("Use original music");
            var sixVoices=Theme.Button("Convert with 6 voices");var maxVoices=Theme.Button("Max voices (8)");
            foreach(var button in new[]{import,instruments,apply,autoMusic,sixVoices,maxVoices,sourcePlay,convertedPlay,stop,all,reset})actions.Controls.Add(button);
