            activity=new MusicActivityMeters{Dock=DockStyle.Fill};var meter=new AudioCapacityBar{Dock=DockStyle.Fill};var musicLayout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5};musicLayout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));musicLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,104));musicLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,136));musicLayout.RowStyles.Add(new RowStyle(SizeType.Percent,100));musicLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,172));musicLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,52));settings.Dock=actions.Dock=details.Dock=DockStyle.Fill;musicLayout.Controls.Add(settings,0,0);musicLayout.Controls.Add(actions,0,1);musicLayout.Controls.Add(details,0,2);musicLayout.Controls.Add(activity,0,3);musicLayout.Controls.Add(meter,0,4);split.Panel2.Controls.Add(musicLayout);
            Action show=delegate{string map=musicMaps.SelectedItem as string;if(map==null)return;var song=audioChanges.Music.FirstOrDefault(m=>m.Map==map);meter.Used=song==null?0:song.Sequence.Length;meter.Capacity=song==null?9383:0xb490-(song.Settings??new MusicSettings()).Origin;meter.Caption=map+": "+(song==null?"original ROM music":meter.Used+" / "+meter.Capacity+" sequence bytes; "+song.Voices+" active SPC tracks (limit "+song.VoiceBudget+")");if(song!=null){voices.Value=Math.Max(1,Math.Min(8,song.VoiceBudget));var mode=song.Settings??new MusicSettings();natural.Checked=mode.NaturalRelease;releaseMs.Value=Math.Max(0,Math.Min(500,mode.ReleaseMs));}if(song!=null)details.Text=map+" <- "+song.Name+"\r\n\r\n"+song.Report;meter.Invalidate();};
            musicMaps.SelectedIndexChanged+=delegate{StopAudio();show();};
            Func<string,ImportedMusic> inputFor=map=>{ImportedMusic input;var song=audioChanges.Music.FirstOrDefault(m=>m.Map==map);return musicSources.TryGetValue(map,out input)?input:song==null?null:song.Source;};
            Func<bool,bool,Task> convert=async (browse,automatic)=>{string map=musicMaps.SelectedItem as string;if(map==null){RefreshAudioMaps();map=musicMaps.SelectedItem as string;}if(map==null){MessageBox.Show(this,"Choose a base ROM first.","Music");return;}string path=null;if(browse)using(var dialog=new OpenFileDialog{Filter="MIDI or Doom MUS|*.mid;*.midi;*.mus"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;path=dialog.FileName;}var input=path==null?inputFor(map):null;if(path==null&&input==null){MessageBox.Show(this,"Import a score first.","Music");return;}int count=(int)voices.Value;double seconds=(double)duration.Value;bool repeat=loop.Checked,keep=keepAssignments.Checked,reduce=fewerVoices.Checked,naturalMode=natural.Checked;int tail=(int)releaseMs.Value;var prior=audioChanges.Music.FirstOrDefault(m=>m.Map==map);try{StopAudio();Enabled=false;details.Text="Reading score, selecting native instruments and compiling...";string basePath=romPath.Text;var result=await Task.Run(delegate{if(path!=null)input=MusicImport.Read(path);byte[] rom=new Rom(basePath,resources).Bytes;var mapping=browse||prior==null||automatic&&!keep?MusicBank.Automatic(rom,input):prior.Settings??new MusicSettings();if(!browse&&prior!=null)MusicBank.PreserveMutes(prior.Settings,mapping);var json=ProjectJson.Create();mapping=json.Deserialize<MusicSettings>(json.Serialize(mapping));mapping.NaturalRelease=naturalMode;mapping.ReleaseMs=tail;return automatic?MusicOptimize.Fit(input,map,count,seconds,repeat,mapping,reduce):MusicImport.Convert(input,map,count,seconds,repeat,mapping);});musicSources[map]=input;audioChanges.Music.RemoveAll(m=>m.Map==map);audioChanges.Music.Add(result);AssetsChanged();show();}catch(Exception ex){if(input!=null)musicSources[map]=input;details.Text="Music conversion stopped: "+ex.Message+"\r\nUse Auto convert / fit to simplify long or dense music.";}finally{Enabled=true;}};
            import.Click+=async delegate{await convert(true,false);};apply.Click+=async delegate{await convert(false,false);};autoMusic.Click+=async delegate{await convert(false,true);};stop.Click+=delegate{StopAudio();};sixVoices.Click+=async delegate{voices.Value=6;fewerVoices.Checked=false;await convert(false,true);};maxVoices.Click+=async delegate{voices.Value=8;fewerVoices.Checked=false;await convert(false,true);};
            instruments.Click+=async delegate{string map=musicMaps.SelectedItem as string;var song=audioChanges.Music.FirstOrDefault(m=>m.Map==map);var input=inputFor(map);if(song==null||input==null){MessageBox.Show(this,"Import a score first.","Instruments");return;}try{MusicSettings mapping;using(var dialog=new MusicMappingDialog(new Rom(romPath.Text,resources).Bytes,input,song.Settings??new MusicSettings())){if(dialog.ShowDialog(this)!=DialogResult.OK)return;mapping=dialog.Settings;}StopAudio();Enabled=false;int count=(int)voices.Value;double seconds=(double)duration.Value;bool repeat=loop.Checked,reduce=fewerVoices.Checked;mapping.NaturalRelease=natural.Checked;mapping.ReleaseMs=(int)releaseMs.Value;details.Text="Rebuilding SPC with the new instrument priorities...";var rebuilt=await Task.Run(()=>MusicOptimize.Fit(input,map,count,seconds,repeat,mapping,reduce));audioChanges.Music.RemoveAll(m=>m.Map==map);audioChanges.Music.Add(rebuilt);musicSources[map]=input;AssetsChanged();show();details.AppendText("\r\nAssignments applied and SPC rebuilt. Priority affects overlapping notes when voices are full.");}catch(Exception ex){details.Text="Assignments were not applied: "+ex.Message;}finally{Enabled=true;}};
            sourcePlay.Click+=async delegate{string map=musicMaps.SelectedItem as string;var input=inputFor(map);if(input==null){MessageBox.Show(this,"Import a score to play its source MIDI.","Music");return;}try{StopAudio();midiPlayer=new MidiPreview();var staged=audioChanges.Music.FirstOrDefault(m=>m.Map==map);activity.StartSource(input,staged==null?null:staged.Settings,(double)previewSeconds.Value);await midiPlayer.Play(input,(double)previewSeconds.Value,staged==null?null:staged.Settings);}catch(Exception ex){details.Text="Source MIDI preview: "+ex.Message;}};
            convertedPlay.Click+=async delegate{
                string map=musicMaps.SelectedItem as string;var song=audioChanges.Music.FirstOrDefault(m=>m.Map==map);SpcPreviewPlayer player=null;
                try{
                    StopAudio();previewCancel=new CancellationTokenSource();var token=previewCancel.Token;double seconds=(double)previewSeconds.Value;string basePath=romPath.Text;
                    convertedPlay.Enabled=false;details.Text="Preparing a short SPC playback buffer...";byte[] driver=null,ram=null;int id=0;
                    await Task.Run(delegate{byte[] rom=new Rom(basePath,resources).Bytes;driver=NativeMusicGate.Driver(rom);if(song==null){int entry=MusicTargets.Read(rom,map);ram=AudioRom.Module(rom,entry>>8);id=entry&255;}else{ram=MusicBank.PreviewRam(rom,song);id=(song.Settings??new MusicSettings()).Song;}});
                    if(token.IsCancellationRequested||IsDisposed)return;player=new SpcPreviewPlayer();spcPlayer=player;
                    await player.Play(driver,ram,id,seconds,delegate{if(!token.IsCancellationRequested&&!IsDisposed&&IsHandleCreated)BeginInvoke((Action)delegate{if(token.IsCancellationRequested||IsDisposed)return;activity.StartStream(player);show();details.AppendText("\r\nStreaming native SPC preview. Playback starts from a short buffer; meters follow the audio device clock. Stop cancels rendering and playback.");});});
                }catch(OperationCanceledException){}catch(Exception ex){if(!IsDisposed)details.Text="SPC preview stopped: "+ex.Message;}
                finally{if(player!=null)player.Dispose();if(spcPlayer==player){spcPlayer=null;if(!IsDisposed)activity.Stop();}if(!IsDisposed)convertedPlay.Enabled=true;}
            };
            reset.Click+=delegate{string map=musicMaps.SelectedItem as string;if(map==null)return;StopAudio();audioChanges.Music.RemoveAll(m=>m.Map==map);musicSources.Remove(map);AssetsChanged();details.Text=map+": original music restored.";show();};
            all.Click+=delegate{string map=musicMaps.SelectedItem as string;var song=audioChanges.Music.FirstOrDefault(m=>m.Map==map);if(song==null)return;string[] names=wad==null?musicMaps.Items.Cast<string>().Where(n=>!MusicTargets.IsSpecial(n)).ToArray():levels.CheckedItems.Cast<string>().ToArray();var json=ProjectJson.Create();foreach(string name in names){var copy=json.Deserialize<MusicReplacement>(json.Serialize(song));copy.Map=name;audioChanges.Music.RemoveAll(m=>m.Map==name);audioChanges.Music.Add(copy);}AssetsChanged();show();};
